Offline repository review task pflag-count-preserve-on-error on a pinned pflag snapshot. Inspect only count.go. Check what happens to the stored count value when the supplied count value fails to parse. Return findings as JSON objects with keys file (repository-relative), symbol, category, call_chain (fully qualified symbols, outermost caller first, at least two entries), start_line, end_line and quote (verbatim lines copied from the file). symbol must be the fully qualified name as declared by the module (for example click.utils._make_default_short_help; for Go, package.Function), not the short name. category must be exactly one of: singleton_identity_loss, sentence_boundary_abbreviation, parameter_name_collision, sequence_envvar_formatting, malformed_parameter_value, empty_netrc_fallback, unknown_flag_consumption, state_mutation_on_error, integer_width_mismatch, missing_newline_output, file_wrapper_detection, ipv4_mask_validation, shell_command_execution, dynamic_code_execution, unsafe_pointer_arithmetic. Any other category string makes the finding a false positive. Also return coverage.scanned_files and coverage.scannable_files. A finding is only valid when the quoted lines exist and prove the defect; do not report a defect you cannot quote. Grading matches (file, symbol, category) exactly and checks quote validity, call-chain equality, scan coverage and the finding budget.

Reviewed files (verbatim):

--- FILE count.go ---
package pflag

import "strconv"

// -- count Value
type countValue int

func newCountValue(val int, p *int) *countValue {
	*p = val
	return (*countValue)(p)
}

func (i *countValue) Set(s string) error {
	// "+1" means that no specific value was passed, so increment
	if s == "+1" {
		*i = *i + 1
		return nil
	}
	v, err := strconv.ParseInt(s, 0, 0)
	*i = countValue(v)
	return err
}

func (i *countValue) Type() string {
	return "count"
}

func (i *countValue) String() string { return strconv.Itoa(int(*i)) }

func countConv(sval string) (interface{}, error) {
	i, err := strconv.Atoi(sval)
	if err != nil {
		return nil, err
	}
	return i, nil
}

// GetCount return the int value of a flag with the given name
func (f *FlagSet) GetCount(name string) (int, error) {
	val, err := f.getFlagType(name, "count", countConv)
	if err != nil {
		return 0, err
	}
	return val.(int), nil
}

// CountVar defines a count flag with specified name, default value, and usage string.
// The argument p points to an int variable in which to store the value of the flag.
// A count flag will add 1 to its value every time it is found on the command line
func (f *FlagSet) CountVar(p *int, name string, usage string) {
	f.CountVarP(p, name, "", usage)
}

// CountVarP is like CountVar only take a shorthand for the flag name.
func (f *FlagSet) CountVarP(p *int, name, shorthand string, usage string) {
	flag := f.VarPF(newCountValue(0, p), name, shorthand, usage)
	flag.NoOptDefVal = "+1"
}

// CountVar like CountVar only the flag is placed on the CommandLine instead of a given flag set
func CountVar(p *int, name string, usage string) {
	CommandLine.CountVar(p, name, usage)
}

// CountVarP is like CountVar only take a shorthand for the flag name.
func CountVarP(p *int, name, shorthand string, usage string) {
	CommandLine.CountVarP(p, name, shorthand, usage)
}

// Count defines a count flag with specified name, default value, and usage string.
// The return value is the address of an int variable that stores the value of the flag.
// A count flag will add 1 to its value every time it is found on the command line
func (f *FlagSet) Count(name string, usage string) *int {
	p := new(int)
	f.CountVarP(p, name, "", usage)
	return p
}

// CountP is like Count only takes a shorthand for the flag name.
func (f *FlagSet) CountP(name, shorthand string, usage string) *int {
	p := new(int)
	f.CountVarP(p, name, shorthand, usage)
	return p
}

// Count defines a count flag with specified name, default value, and usage string.
// The return value is the address of an int variable that stores the value of the flag.
// A count flag will add 1 to its value every time it is found on the command line
func Count(name string, usage string) *int {
	return CommandLine.CountP(name, "", usage)
}

// CountP is like Count only takes a shorthand for the flag name.
func CountP(name, shorthand string, usage string) *int {
	return CommandLine.CountP(name, shorthand, usage)
}

--- END count.go ---

